class R:
    status = 200
    def __init__(self):
        self.n = 0
    def read(self):
        return b'{"v": 42}'
c = MiniClient('http://api', transport=lambda u: R())
assert c.get('/v') == {'v': 42}

calls = []
class R:
    status = 404
    def read(self):
        return b'{}'
def transport(u):
    calls.append(u)
    return R()
c = MiniClient('http://api', transport=transport)
try:
    c.get('/missing')
    failed = False
except ApiError:
    failed = True
assert failed
assert len(calls) == 1, 'client errors (4xx) must not be retried'

class Flaky:
    def __init__(self):
        self.calls = 0
    def read(self):
        return b'{}'
flaky = Flaky()
def transport(u):
    flaky.calls += 1
    class R:
        status = 503 if flaky.calls == 1 else 200
        def read(self):
            return b'{"ok": true}'
    return R()
c = MiniClient('http://api', transport=transport)
assert c.get('/x') == {'ok': True}
assert flaky.calls == 2

def transport(u):
    class R:
        status = 500
        def read(self):
            return b'{}'
    return R()
c = MiniClient('http://api', transport=transport)
try:
    c.get('/down')
    failed = False
except ApiError as e:
    failed = 'exhausted' in str(e)
assert failed
